"""Text truncation for previews."""


def truncate(text, limit):
    """Shorten text to at most `limit` characters, cutting at a word boundary and adding "..."."""
    if len(text) <= limit:
        return text
    budget = max(limit - 3, 0)  # room left for the text once "..." is appended
    if budget < len(text) and text[budget].isspace():
        # The cut falls right before a space, so the words before it all fit.
        head = text[:budget].rstrip()
    else:
        head = text[:budget]
        idx = max(head.rfind(" "), head.rfind("\t"), head.rfind("\n"))
        if idx > 0:
            head = head[:idx].rstrip()
        # else: a single word longer than the budget; fall back to a hard cut.
    return head + "..."

